sp_widget.client_script:
function($scope, $rootScope) {
    var chartRclLinha = null;

    $scope.anoSelecionado = "";

    function carregarDadosRcl() {
        var filtros = {
            ano: $scope.anoSelecionado || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoRCL || [];
            montarGraficoRcl(dados);
        });
    }

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionado = ano;
        carregarDadosRcl();
    });

    carregarDadosRcl();

    function montarGraficoRcl(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartRclLinha) {
                chartRclLinha.destroy();
                chartRclLinha = null;
            }
            $scope.exibirGraficoRcl = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoRcl = true;
        $scope.$applyAsync();

        // Ordenar anos (função tradicional)
        listaDados.sort(function(a, b) {
            return a.ano - b.ano;
        });

        // Mapear anos
        var anos = [];
        for (var i = 0; i < listaDados.length; i++) {
            anos.push(listaDados[i].ano);
        }

        // Mapear valores RCL Normal
        var valoresNormais = [];
        for (var j = 0; j < listaDados.length; j++) {
            valoresNormais.push(listaDados[j].somaRclNormal / 1000000);
        }

        // Mapear valores RCL Ajustada
        var valoresAjustados = [];
        for (var k = 0; k < listaDados.length; k++) {
            valoresAjustados.push(listaDados[k].somaRclAjustada / 1000000);
        }

        var ctx = document.getElementById('graficoRclLinha').getContext('2d');

        if (chartRclLinha) {
            chartRclLinha.destroy();
        }

        chartRclLinha = new Chart(ctx, {
            type: 'line',
            data: {
                labels: anos,
                datasets: [
                    {
                        label: 'RCL Normal',
                        data: valoresNormais,
                        borderColor: '#007bff',
                        backgroundColor: 'rgba(0, 123, 255, 0.3)',
                        fill: false,
                        tension: 0.3,
                        pointRadius: 5,
                        pointHoverRadius: 7
                    },
                    {
                        label: 'RCL Ajustada',
                        data: valoresAjustados,
                        borderColor: '#120a8f',
                        backgroundColor: '#120a8f',
                        fill: false,
                        tension: 0.3,
                        pointRadius: 5,
                        pointHoverRadius: 7
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: { display: true, text: 'Ano' },
											 offset: true 
                    },
                    y: {
                        beginAtZero: true,
                        title: { display: true, text: 'Valor (Milhões de R$)' },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + value.toLocaleString('pt-BR') + ' mi';
                            }
                        }
                    }
                },
                plugins: {
                    legend: { position: 'top' },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR') + ' mi';
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
	 input = input || {};


    var anoFiltro = input.ano || ""; // caso queira filtrar ano
    var grRCL = new GlideAggregate('x_sded9_portal_t_0_u_rcl_basica');

    if (anoFiltro !== "") {
        grRCL.addQuery('u_ano', anoFiltro);
    }

    // Agrupamos por ano para somar por ano
    grRCL.addAggregate('SUM', 'u_rcl_normal');
    grRCL.addAggregate('SUM', 'u_rcl_ajustada');
    grRCL.groupBy('u_ano');
    grRCL.orderBy('u_ano');
    grRCL.query();

    var listaRCL = [];

    while (grRCL.next()) {
        listaRCL.push({
            ano: parseInt(grRCL.getValue('u_ano'), 10),
            somaRclNormal: parseFloat(grRCL.getAggregate('SUM', 'u_rcl_normal')) || 0,
            somaRclAjustada: parseFloat(grRCL.getAggregate('SUM', 'u_rcl_ajustada')) || 0
        });
    }

    data.dadosGraficoRCL = listaRCL;
})();
